import {CheckBox, IndexPath} from '@ui-kitten/components';
import {Pressable, View} from 'react-native';
import TextCM from '../../../../../../components/Text';
import {useTaskService} from '../../../../../../../hooks/apiHooks/useAPI';
import {useEffect, useState} from 'react';
import {IConfigTaskDaily} from '../../../../helper';
import DropdownListCM from '../../../../../../components/DropDownList';
import ButtonCM from '../../../../../../components/Button';
import {DateUtils} from '../../../../../../../utils';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import ModalCustom from './modalCustom';
import Toast from 'react-native-toast-message';

type Props = {
  taskId?: string;
  startDate?: string;
};

const TaskRepeat = ({taskId, startDate}: Props) => {
  const [dailyConfig, setDailyConfig] = useState<IConfigTaskDaily>();
  const [check, setCheck] = useState(false);
  const [currentDay, setCurrentDay] = useState(
    startDate ? new Date(startDate) : new Date(),
  );
  const [openModalCustom, setOpenModalCustom] = useState(false);
  const [disableSelect, setDisableSelect] = useState(true);
  const [select, setSelect] = useState<IndexPath>();
  const [listSection, setListSection] = useState<
    {
      label: string;
      value: string;
    }[]
  >([]);
  const TaskService = useTaskService();

  useEffect(() => {
    getConfigTaskDaily();
  }, []);

  const getConfigTaskDaily = async () => {
    const dataResp = await TaskService.getDailyTaskConfig(taskId as string);
    if (dataResp !== 'noContent') {
      setCheck(true);
      handleChangeDowndown(dataResp);
    } else {
      setCheck(false);
      initDropdown({});
    }
  };

  const handleChangeDowndown = (dataResp: IConfigTaskDaily) => {
    setDailyConfig(dataResp);
    const selection = JSON.stringify(
      parseValue({
        ...dataResp,
        dayOfWeek: JSON.stringify(dataResp.dayOfWeek),
      }),
    );
    const label = getCustomLabelDate(dataResp);
    setListSection([
      {
        label: label,
        value: selection,
      },
    ]);
    initDropdown({
      label: label,
      value: selection,
    });
    setSelect(new IndexPath(0));
  };

  const parseValue = (time: IConfigTaskDaily) => {
    let parseTime: any = {
      scheduleType: 0,
      scheduleTime: 0,
      dayOfWeek: null,
      weekOfMonth: 0,
      dayOfMonth: 0,
      startDate: '',
      dayOM: null,
      endType: '',
      endDate: null,
      timeLoop: null,
    };
    parseTime.scheduleTime = time.scheduleTime;
    parseTime.scheduleType = time.scheduleType;
    parseTime.dayOfWeek = time.dayOfWeek ? JSON.parse(time.dayOfWeek) : null;
    parseTime.weekOfMonth = time.weekOfMonth;
    parseTime.dayOfMonth = time.dayOfMonth;
    parseTime.startDate = formatToIsoDate(time.startDate, 'start');
    parseTime.endType = time.endType;
    parseTime.endDate = time.endDate;
    parseTime.timeLoop = time.timeLoop;

    if (time.dayOM) {
      parseTime.dayOM = time.dayOM;
      parseTime = {...parseTime, ...JSON.parse(time.dayOM)};
    }
    // check if schedule type is month => set attribute dayOM (day of month)
    else if (time.scheduleType === 2) {
      if (time.dayOfMonth) {
        parseTime.dayOM = JSON.stringify({dayOfMonth: parseTime.dayOfMonth});
        parseTime.weekOfMonth = null;
        parseTime.dayOfWeek = null;
      } else if (time.weekOfMonth && time.dayOfWeek) {
        parseTime.dayOM = JSON.stringify({
          weekOfMonth: parseTime.weekOfMonth,
          dayOfWeek: parseTime.dayOfWeek,
        });
        parseTime.dayOfMonth = null;
      }
    }

    if (time.scheduleType === 0) {
      parseTime.dayOfWeek = null;
      parseTime.weekOfMonth = null;
      parseTime.dayOfMonth = null;
    } else if (time.scheduleType === 1) {
      parseTime.weekOfMonth = null;
      parseTime.dayOfMonth = null;
    } else if (time.scheduleType === 3) {
      parseTime.dayOfWeek = null;
      parseTime.weekOfMonth = null;
      parseTime.dayOfMonth = null;
    }

    // check end type of schedule
    if (time.endType === 'N') {
      parseTime.endDate = null;
      parseTime.timeLoop = null;
    } else if (time.endType === 'O') {
      parseTime.timeLoop = null;
    } else if (time.endType === 'R') {
      parseTime.endDate = null;
    }

    return parseTime;
  };

  const initDropdown = (dataInit?: any) => {
    const typeDateArr: (
      | 'day'
      | 'week'
      | 'dayOfMonth'
      | 'weekOfMonth'
      | 'year'
    )[] = ['day', 'week', 'dayOfMonth', 'weekOfMonth', 'year'];
    const data = typeDateArr?.map(t => ({
      label: getLabelDate(t, currentDay, currentDay),
      value: JSON.stringify(getValueDate(t, currentDay)),
    }));
    setListSection(
      [
        dataInit,
        ...data,
        {
          label: 'Tuỳ chỉnh',
          value: 'custom',
        },
      ]?.filter(d => d?.value && d?.label),
    );
  };

  function formatToIsoDate(
    value: string,
    type: 'start' | 'end' = 'start',
  ): string | null {
    if (!value?.trim()) {
      return null;
    }

    const date = new Date(value);

    // Adjust to start or end of day in UTC+7
    if (type === 'start') {
      date.setUTCHours(0 - 7, 0, 0, 0); // set to 00:00:00.000 UTC+7 (which is 17:00 UTC previous day)
    } else {
      date.setUTCHours(23 - 7, 59, 59, 0); // set to 23:59:59.000 UTC+7 (which is 16:59:59 UTC)
    }

    return date.toISOString();
  }

  /**
   *
   * @param type: week | month | year
   * @param date
   * scheduleType: 0 - day; 1 - week; 2 - month; 3 - year
   * scheduleTime: the time to repeat follow per scheduleType
   * dayOfWeek: ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'] is the day of week to repeat follow by scheduleType = week
   * weekOfMonth: number => is the order of week in month to repeat follow by scheduleType = month
   * dayOfMonth: number => is the order of day in month to repeat follow by scheduleType = month
   */
  const getValueDate = (
    type: 'day' | 'week' | 'dayOfMonth' | 'weekOfMonth' | 'year',
    date: Date,
  ) => {
    let scheduleType: 0 | 1 | 2 | 3;
    let scheduleTime: number = 1;
    let dayOfWeek: string[] = [];
    let weekOfMonth: number;
    let dayOfMonth: number;
    let startDate = formatToIsoDate(new Date().toISOString(), 'start');
    let dayOM: string;

    if (type === 'day') {
      scheduleType = 0;
    }
    if (type === 'week') {
      scheduleType = 1;
      const dayInW = date.getDay();
      dayOfWeek = [['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][dayInW]];
    } else if (type === 'dayOfMonth') {
      scheduleType = 2;
      dayOfMonth = date.getDate();
      dayOM = JSON.stringify({dayOfMonth: date.getDate()});
    } else if (type === 'weekOfMonth') {
      scheduleType = 2;
      const dayInW = date.getDay();
      weekOfMonth = Math.ceil(date.getDate() / 7);
      dayOfWeek = [['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][dayInW]];
      dayOM = JSON.stringify({
        weekOfMonth: Math.ceil(date.getDate() / 7),
        dayOfWeek: [['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][dayInW]],
      });
    } else if (type === 'year') {
      scheduleType = 3;
    }

    return {
      scheduleType,
      scheduleTime,
      dayOfWeek,
      weekOfMonth,
      dayOfMonth,
      startDate,
      dayOM,
      endType: 'N',
      endDate: null,
      timeLoop: null,
    };
  };

  const getLabelDate = (
    type: 'day' | 'week' | 'dayOfMonth' | 'weekOfMonth' | 'year',
    date: Date,
    currentDay: Date,
  ) => {
    if (type === 'day') {
      return 'Hằng ngày';
    }
    if (type === 'week') {
      const dayInW = date.getDay();
      return `${dayInW > 0 ? 'Thứ ' + (dayInW + 1) : 'Chủ nhật'} hàng tuần`;
    }
    if (type === 'dayOfMonth') {
      const dayInM = date.getDate();
      return `Ngày ${dayInM} hàng tháng`;
    } else if (type === 'weekOfMonth') {
      return `${
        currentDay.getDay() > 0
          ? 'Thứ ' + (currentDay.getDay() + 1)
          : 'Chủ nhật'
      } tuần thứ ${Math.ceil(currentDay.getDate() / 7)} hàng tháng`;
    }
    if (type === 'year') {
      const dayInM = date.getDate();
      const month = date.getMonth() + 1;
      return `Ngày ${dayInM} tháng ${month} hàng năm`;
    }
    return '';
  };

  const getCustomLabelDate = (selection: IConfigTaskDaily) => {
    const value: IConfigTaskDaily = selection;
    let label = '';
    if (value.scheduleTime > 1) {
      label = `Lặp lại mỗi ${value.scheduleTime} `;
    } else {
      label = `Lặp lại hàng `;
    }
    if (value.scheduleType === 0) {
      label += 'ngày';
    } else if (value.scheduleType === 1) {
      label += 'tuần';
      if (value.dayOfWeek) {
        label += ` vào ${getDay(JSON.parse(value.dayOfWeek))}`;
      }
    } else if (value.scheduleType === 2) {
      label += 'tháng';
      if (value.dayOfWeek && value.weekOfMonth) {
        label += ` vào ${getDay(JSON.parse(value.dayOfWeek))} tuần ${
          value.weekOfMonth
        }`;
      } else if (value.dayOfMonth) {
        label += ` vào ngày ${value.dayOfMonth}`;
      }
    } else if (value.scheduleType === 3) {
      label += 'năm';
    }

    if (value.endType === 'O') {
      label += `, kết thúc vào ${DateUtils.convertDateToDDMMYYYY(
        value.endDate,
      )}`;
    } else if (value.endType === 'R') {
      label += `, kết thúc sau ${value.timeLoop} lần lặp`;
    }

    return label;
  };

  const getDay = (value: any) => {
    return value?.reduce((tot: any, curr: any, index: any) => {
      let v = '';
      if (curr === 'MON') {
        v = 'Thứ 2';
      }
      if (curr === 'TUE') {
        v = 'Thứ 3';
      }
      if (curr === 'WED') {
        v = 'Thứ 4';
      }
      if (curr === 'THU') {
        v = 'Thứ 5';
      }
      if (curr === 'FRI') {
        v = 'Thứ 6';
      }
      if (curr === 'SAT') {
        v = 'Thứ 7';
      }
      if (curr === 'SUN') {
        v = 'Chủ nhật';
      }
      return tot + (index > 0 ? ', ' : '') + v;
    }, '');
  };

  const handleSelect = (item: IndexPath) => {
    if (item) {
      const dataSelect = listSection[item.row];
      if (dataSelect?.value === 'custom') {
        setOpenModalCustom(true);
        return;
      }
    }
    setSelect(item);
  };

  const handleSubmit = async () => {
    try {
      if (select) {
        const dataSelect = listSection[select.row];
        console.log(dataSelect);
        const dataBody = JSON.parse(dataSelect?.value || '{}');
        const dataResp = await TaskService.createDailyTaskConfig({
          ...dataBody,
          taskId,
        });
        if (dataResp) {
          setDailyConfig(dataResp);
          Toast.show({
            type: 'success',
            text1: 'Thông báo',
            text2: 'Lặp lại công việc thành công',
          });
          setDisableSelect(true);
        }
      }
    } catch (error) {}
  };

  const handleSubmitCustom = async (data: IConfigTaskDaily) => {
    try {
      const dataResp = await TaskService.createDailyTaskConfig({
        ...data,
        taskId,
      });
      if (dataResp) {
        handleChangeDowndown(dataResp);
        Toast.show({
          type: 'success',
          text1: 'Thông báo',
          text2: 'Lặp lại công việc thành công',
        });
      }
    } catch (error) {
    } finally {
      setDisableSelect(true);
      setOpenModalCustom(false);
    }
  };

  return (
    <View>
      <CheckBox
        checked={check}
        children={<TextCM>Công việc lặp lại hằng ngày</TextCM>}
        onChange={check => setCheck(check)}
      />

      {check && (
        <View
          style={{
            marginTop: 10,
          }}>
          <DropdownListCM
            label="Thời gian lặp lại công việc"
            onSelect={(value: any) => handleSelect(value)}
            size="medium"
            listData={listSection}
            valueSelect={select}
            placeholder="Chọn thời gian lặp lại"
            disabled={disableSelect}
          />

          <View
            style={{
              marginTop: 10,
            }}>
            {disableSelect ? (
              <Pressable onPress={() => setDisableSelect(false)}>
                <TextCM>Chỉnh sửa</TextCM>
              </Pressable>
            ) : (
              <View
                style={{
                  flexDirection: 'row',
                  alignItems: 'center',
                  justifyContent: 'flex-end',
                  columnGap: 8,
                }}>
                <ButtonCM
                  style={{
                    height: 30,
                  }}
                  label="Huỷ"
                  onPress={() => setDisableSelect(true)}
                />
                <ButtonCM
                  style={{
                    height: 30,
                  }}
                  disabled={!select ? true : false}
                  label="Lưu"
                  onPress={handleSubmit}
                />
              </View>
            )}
          </View>
        </View>
      )}

      <ModalFullScreen
        isVisible={openModalCustom}
        children={
          <ModalCustom
            dateProp={currentDay}
            onClose={() => setOpenModalCustom(false)}
            onSave={handleSubmitCustom}
          />
        }
      />
    </View>
  );
};

export default TaskRepeat;
