import {
  Datepicker,
  Divider,
  Icon,
  IndexPath,
  Radio,
  RadioGroup,
} from '@ui-kitten/components';
import HeaderCM from '../../../../../../../components/Header/HeaderCM';
import {FlatList, Pressable, TextInput, View} from 'react-native';
import TextCM from '../../../../../../../components/Text';
import DropdownListCM from '../../../../../../../components/DropDownList';
import {listDayOfW, listRepeatType} from './helper';
import {Color} from '../../../../../../../../constants';
import {useEffect, useState} from 'react';
import ButtonCM from '../../../../../../../components/Button';
import styles from './styles';

type Props = {
  onClose: () => void;
  dateProp: Date;
  onSave: (data: any) => void;
};

const ModalCustom = ({onClose, dateProp, onSave}: Props) => {
  const [dataForm, setDataForm] = useState<{
    timeLoop: string;
    dayOfWeek: string[];
    endDate: Date;
    scheduleTime: string;
    scheduleType: number;
    endType: 'N' | 'O' | 'R';
    valueMonth?: string;
  }>({
    timeLoop: '1',
    dayOfWeek: ['FRI'],
    endDate: new Date(),
    scheduleTime: '1',
    scheduleType: 1,
    endType: 'N',
    valueMonth: '',
  });
  const [repeatType, setRepeatType] = useState<IndexPath>(
    new IndexPath(dataForm.scheduleType),
  );
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [listDayOfM, setListDayOfM] = useState<
    {
      label: string;
      value: string;
    }[]
  >([]);
  const [dataMonth, setDataMonth] = useState<IndexPath>(new IndexPath(0));

  useEffect(() => {
    handleInit();
  }, []);

  const handleInit = () => {
    const listDayOfM = [
      {
        label: `Ngày ${dateProp.getDate()} hàng tháng`,
        value: JSON.stringify({dayOfMonth: dateProp.getDate()}),
      },
      {
        label: `${
          dateProp.getDay() > 0 ? 'Thứ ' + (dateProp.getDay() + 1) : 'Chủ nhật'
        } tuần thứ ${Math.ceil(dateProp.getDate() / 7)} hàng tháng`,
        value: JSON.stringify({
          weekOfMonth: Math.ceil(dateProp.getDate() / 7),
          dayOfWeek: [
            ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][
              dateProp.getDay()
            ],
          ],
        }),
      },
    ];
    setListDayOfM(listDayOfM);
  };

  const handleSubmit = () => {
    let dataBody: any;
    if (dataForm?.scheduleType === 0 || dataForm?.scheduleType === 3) {
      dataBody = {
        scheduleType: dataForm?.scheduleType,
        scheduleTime: dataForm?.scheduleTime,
        endType: dataForm?.endType,
        startDate: dateProp,
      };
    } else if (dataForm?.scheduleType === 1) {
      dataBody = {
        scheduleType: dataForm?.scheduleType,
        scheduleTime: dataForm?.scheduleTime,
        dayOfWeek: dataForm?.dayOfWeek,
        endType: dataForm?.endType,
        startDate: dateProp,
      };
    } else if (dataForm?.scheduleType === 2) {
      dataBody = {
        scheduleType: dataForm?.scheduleType,
        scheduleTime: dataForm?.scheduleTime,
        endType: dataForm?.endType,
        startDate: dateProp,
        ...JSON.parse(dataForm?.valueMonth || '{}'),
      };
    }
    if (dataForm?.endType === 'O') {
      dataBody.endDate = dataForm?.endDate;
    } else if (dataForm?.endType === 'R') {
      dataBody.timeLoop = dataForm?.timeLoop;
    }
    onSave(dataBody);
  };

  const handleChangeValueListOfW = (item: string) => {
    if (dataForm?.dayOfWeek?.includes(item)) {
      setDataForm({
        ...dataForm,
        dayOfWeek: dataForm?.dayOfWeek?.filter((i: string) => i !== item),
      });
    } else {
      setDataForm({
        ...dataForm,
        dayOfWeek: [...dataForm?.dayOfWeek, item],
      });
    }
  };

  const handleChangeRepeatType = (item: IndexPath) => {
    setRepeatType(item);
    setDataForm({
      ...dataForm,
      scheduleType: item?.row,
    });
  };

  const handleChangeDataForm = (value: any, type: any) => {
    setDataForm({
      ...dataForm,
      [type]: value,
    });
  };

  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#00204D',
        }}
        fillIconBackLeft="#00204DB2"
        title={'Custom'}
        onPressIconLeft={onClose}
      />
      <Divider />

      <View style={{padding: 10, flex: 1}}>
        <View style={{marginBottom: 10, rowGap: 10}}>
          <TextCM style={styles.txtHeader}>Lặp lại mỗi</TextCM>
          <View
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              justifyContent: 'space-between',
              columnGap: 10,
            }}>
            <TextInput
              keyboardType="numeric"
              style={{
                flex: 1,
                borderWidth: 1,
                height: 38,
                borderRadius: 8,
                borderColor: Color.borderColor,
                paddingHorizontal: 16,
              }}
              value={dataForm?.scheduleTime}
              onChangeText={value =>
                handleChangeDataForm(value, 'scheduleTime')
              }
            />
            <DropdownListCM
              size="medium"
              style={{flex: 1}}
              onSelect={handleChangeRepeatType}
              listData={listRepeatType}
              valueSelect={repeatType}
              isShowClear={false}
            />
          </View>
        </View>

        {(repeatType?.row === 1 || repeatType?.row === 2) && (
          <>
            <View style={{marginBottom: 16, rowGap: 10}}>
              <TextCM style={styles.txtHeader}>Lặp lại vào</TextCM>
              {repeatType?.row === 1 && (
                <FlatList
                  contentContainerStyle={{gap: 10}}
                  data={listDayOfW}
                  horizontal
                  renderItem={({item, index}) => (
                    <Pressable
                      onPress={() => handleChangeValueListOfW(item)}
                      style={{
                        borderWidth: dataForm?.dayOfWeek?.includes(item)
                          ? 0
                          : 1,
                        height: 38,
                        width: 38,
                        borderRadius: 38 / 2,
                        borderColor: Color.borderColor,
                        alignItems: 'center',
                        justifyContent: 'center',
                        backgroundColor: dataForm?.dayOfWeek?.includes(item)
                          ? Color.BgPrimary
                          : '#fff',
                      }}>
                      <TextCM
                        style={{
                          color: dataForm?.dayOfWeek?.includes(item)
                            ? '#fff'
                            : Color.Text,
                        }}>
                        {item}
                      </TextCM>
                    </Pressable>
                  )}
                />
              )}

              {repeatType?.row === 2 && (
                <DropdownListCM
                  listData={listDayOfM}
                  size="medium"
                  valueSelect={dataMonth}
                  isShowClear={false}
                  onSelect={(item: any) => {
                    setDataMonth(item);
                    handleChangeDataForm(
                      listDayOfM?.[item?.row]?.value,
                      'valueMonth',
                    );
                  }}
                />
              )}
            </View>
          </>
        )}

        <View>
          <TextCM style={styles.txtHeader}>Kết thúc vào</TextCM>
          <View>
            <RadioGroup
              selectedIndex={selectedIndex}
              onChange={index => {
                setSelectedIndex(index);
                handleChangeDataForm(
                  index === 0 ? 'N' : index === 1 ? 'O' : 'R',
                  'endType',
                );
              }}>
              <Radio>Không có ngày kết thúc</Radio>
              <Radio>Vào ngày</Radio>
              <Radio>Sau khi lặp lại</Radio>
            </RadioGroup>
          </View>
        </View>
        {selectedIndex === 2 && (
          <View
            style={{
              position: 'relative',
              height: 38,
            }}>
            <TextInput
              keyboardType="numeric"
              style={{
                borderWidth: 1,
                height: 38,
                borderRadius: 8,
                borderColor: Color.borderColor,
                paddingHorizontal: 16,
              }}
              value={dataForm?.timeLoop}
              onChangeText={value => handleChangeDataForm(value, 'timeLoop')}
            />
            <TextCM
              style={{
                position: 'absolute',
                right: 16,
                top: 8,
                lineHeight: 22,
              }}>
              Lần
            </TextCM>
          </View>
        )}

        {selectedIndex === 1 && (
          <Datepicker
            accessoryRight={<Icon name="calendar-outline" />}
            date={dataForm.endDate}
            min={new Date(1900, 0, 0)}
            onSelect={nextDate => handleChangeDataForm(nextDate, 'endDate')}
          />
        )}
      </View>

      <ButtonCM
        style={{
          marginHorizontal: 16,
        }}
        label="Lưu"
        onPress={handleSubmit}
      />
    </>
  );
};

export default ModalCustom;
