import {ScrollView, Text, View} from 'react-native';
import {PieChart} from 'react-native-gifted-charts';
import {Organization} from '../../../../model/interface/dashboard.interface';
import {useEffect, useState} from 'react';
import {Font} from '../../../../constants';
type Props = {
  organization: Organization[];
};
type PieData = {
  name: string;
  value: number;
  color: string;
};
const DashboardDonut = ({organization}: Props) => {
  const [totalTask, setTotalTask] = useState<number>(0);
  const [pieData, setPieData] = useState<PieData[]>([]);
  const getRandomColor = () => {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
  };
  const tranformData = (organization: Organization[]) => {
    const initColor = ['#00A3FF', '#FF69B4', '#943CDD', '#90EE90'];
    let totalTask = 0;
    const data = organization
      .sort((a, b) => b.taskCountOrg - a.taskCountOrg)
      .map((item, index) => {
        const value = item.taskCountOrg;
        const name = item.name;
        totalTask += item.taskCountOrg;
        return {
          value,
          color: index < 3 ? initColor[index] : getRandomColor(),
          name,
        };
      });
    setTotalTask(totalTask);
    setPieData(data);
  };
  useEffect(() => {
    tranformData(organization);
  }, [organization]);
  const renderDot = (color: string) => {
    return (
      <View
        style={{
          height: 10,
          width: 10,
          borderRadius: 5,
          backgroundColor: color,
          marginRight: 10,
        }}
      />
    );
  };
  const renderLegendComponent = () => {
    return (
      <ScrollView horizontal>
        {pieData.map(item => {
          return (
            <View
              key={item.name}
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                padding: 5,
              }}>
              {renderDot(item.color)}
              <Text
                style={{
                  color: item.color,
                }}>{`${item.name}: ${item.value} `}</Text>
            </View>
          );
        })}
      </ScrollView>
    );
  };
  return (
    <View
      style={{
        margin: 10,
        padding: 20,
        borderRadius: 20,
        backgroundColor: '#fff',
      }}>
      <Text style={{fontSize: 16, fontFamily: Font.InterBold700}}>
        {'Tổng số task theo phòng ban'}
      </Text>
      <View style={{padding: 20, alignItems: 'center'}}>
        <PieChart
          data={pieData}
          donut
          radius={90}
          innerRadius={60}
          innerCircleColor={'#fff'}
          centerLabelComponent={() => {
            return (
              <View style={{justifyContent: 'center', alignItems: 'center'}}>
                <Text
                  style={{
                    fontSize: 22,
                    color: 'black',
                    fontFamily: Font.InterBold700,
                  }}>
                  {totalTask}
                </Text>
                <Text style={{fontSize: 14, color: 'black'}}>
                  {'Tổng cộng'}
                </Text>
              </View>
            );
          }}
        />
      </View>
      {renderLegendComponent()}
    </View>
  );
};

export default DashboardDonut;
