import {
  CalendarRange,
  Divider,
  IndexPath,
  RangeDatepicker,
} from '@ui-kitten/components';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {ScrollView, View} from 'react-native';
import InputCM from '../../../../components/TextField/InputCM';
import DropdownListCM from '../../../../components/DropDownList';
import {IFormBuilder, IFormBuilderKeys, PRIORITIES} from './helper';
import TextFieldCM from '../../../../components/TextField';
import TextCM from '../../../../components/Text';
import {useState} from 'react';
import styles from './styles';
import ButtonCM from '../../../../components/Button';
import {isEmpty} from 'lodash';
import {useBoardService} from '../../../../../hooks/apiHooks/useAPI';
import useBoardStore from '../../store';
import {KEY_TASK} from '../../helper';
import Toast from 'react-native-toast-message';

type Props = {
  onClose?: () => void;
};

const CreateNewTaskScreen = ({onClose}: Props) => {
  const [range, setRange] = useState<CalendarRange<Date>>({});
  const [dataForm, setDataForm] = useState<IFormBuilder>({});
  const [errors, setErrors] =
    useState<Partial<Record<IFormBuilderKeys, string>>>();
  const [priorityIndex, setPriorityIndex] = useState<IndexPath | undefined>(
    undefined,
  );

  const {listHeaderTask, addListHeaderTaskByKey} = useBoardStore();
  const BoardServices = useBoardService();

  const handleSubmit = async () => {
    if (!dataForm.name?.trim()) {
      setErrors(prev => ({
        ...prev,
        name: 'Không được để trống',
      }));
      return;
    }
    const listTask = {
      ...dataForm,
      priority: PRIORITIES?.[priorityIndex?.row as number]?.value,
      startDate: range.startDate,
      dueDate: range.endDate,
      groupTaskList: [
        {
          name: 'todo',
          attr: JSON.stringify({
            type: 'todo',
            status: 'open',
            color: '#00A3FF',
            order: 1,
          }),
          type: 'todo',
        },
        {
          name: 'processing',
          attr: JSON.stringify({
            type: 'processing',
            status: 'open',
            color: '#EF5DA8',
            order: 2,
          }),
          type: 'processing',
        },
        {
          name: 'approved',
          attr: JSON.stringify({
            type: 'approved',
            status: 'open',
            color: '#A855F7',
            order: 3,
          }),
          type: 'approved',
        },
        {
          name: 'completed',
          attr: JSON.stringify({
            type: 'completed',
            status: 'open',
            color: '#22C55E',
            order: 4,
          }),
          type: 'completed',
        },
      ],
      assignTaskList: [],
      template: false,
    };
    try {
      const data = await BoardServices.saveListTask(listTask);
      if (data) {
        const newListTask =
          listHeaderTask.find(header => header.key === KEY_TASK['my-task'])
            ?.child || [];
        addListHeaderTaskByKey([data, ...newListTask], KEY_TASK['my-task']);
        Toast.show({
          type: 'success',
          text1: 'Thông báo',
          text2: 'Tạo mới không gian thành công',
        });
        onClose?.();
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Tạo mới không gian không thành công',
        });
      }
    } catch (error) {}
  };

  const handleChangeValue = (key: IFormBuilderKeys, value: any) => {
    setDataForm(prev => ({
      ...prev,
      [key]: value,
    }));

    if (key === 'name' && !value?.trim()) {
      setErrors(prev => ({
        ...prev,
        name: 'Không được để trống',
      }));
    } else {
      setErrors(prev => {
        const update = {...prev};
        delete update[key];
        return update;
      });
    }
  };
  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        onPressIconLeft={() => {
          onClose?.();
        }}
        title="Thêm mới không gian làm việc"
        alignment="start"
      />
      <Divider />

      <ScrollView
        contentContainerStyle={{rowGap: 10}}
        style={{flex: 1, padding: 16}}>
        <InputCM
          isRequired
          label={'Tên không gian'}
          placeholder="Nhập tên không gian"
          value={dataForm.name}
          onChangeText={text => handleChangeValue('name', text)}
          captionText={errors?.name}
        />

        <TextCM>{'Ngày thực hiện'}</TextCM>
        <RangeDatepicker
          range={range}
          size="medium"
          controlStyle={styles.calender}
          onSelect={nextRange => setRange(nextRange)}
          min={new Date(1900, 0, 0)}
          placeholder={props => (
            <TextCM {...props}>{'Từ ngày đến ngày'}</TextCM>
          )}
        />
        <DropdownListCM
          label={'Độ ưu tiên'}
          placeholder="Chọn độ ưu tiên"
          size="medium"
          valueSelect={priorityIndex}
          onSelect={setPriorityIndex}
          listData={PRIORITIES}
        />
        <View style={{rowGap: 6}}>
          <TextCM>Mô tả</TextCM>
          <TextFieldCM
            onChangeText={text => handleChangeValue('description', text)}
            value={dataForm.description}
            label="Nhập mô tả"
            multiline
            maxLength={500}
          />
        </View>
      </ScrollView>

      <View
        style={{
          paddingHorizontal: 16,
          flexDirection: 'row',
          alignItems: 'center',
          columnGap: 8,
        }}>
        <ButtonCM style={{flex: 1}} onPress={() => {}} label="Mẫu" />
        <ButtonCM
          disabled={isEmpty(errors) ? false : true}
          style={{flex: 1}}
          onPress={handleSubmit}
          label="Lưu"
        />
      </View>
    </>
  );
};

export default CreateNewTaskScreen;
