import {useEffect, useState} from 'react';
import {Assignee} from '../../../../model/interface/dashboard.interface';
import TableCM from '../../../components/Table';
import {Image, StyleSheet, Text, View} from 'react-native';
import {Color, Font, String} from '../../../../constants';
import TextCM from '../../../components/Text';

type Props = {
  asignee: Assignee[];
};
const DashboardAsignee = ({asignee}: Props) => {
  const [dataTable, setDataTable] = useState<any>([]);
  const tranformData = (asignee: Assignee[]) => {
    const asgineeeeee = asignee
      .sort((a, b) => b.taskCount - a.taskCount)
      .map((item, index) => {
        return {
          STT: index,
          Assignee: (
            <View style={styles.container}>
              <View style={styles.avatarContainer}>
                <Image
                  width={50}
                  height={50}
                  borderRadius={25}
                  source={{
                    uri: item.avatar || String.DEFAULT_IMAGE,
                  }}
                />
              </View>
              <View style={styles.infoContainer}>
                <Text style={styles.username}>{item.name}</Text>
                <Text style={styles.email}>{item.email}</Text>
              </View>
            </View>
          ),
          Quantity: item.taskCount || 0,
        };
      });
    return asgineeeeee;
  };
  useEffect(() => {
    setDataTable(tranformData(asignee));
  }, [asignee]);
  return (
    <View style={{padding: 10}}>
      <TextCM
        style={{
          fontSize: 16,
          fontFamily: Font.InterBold700,
          padding: 20,
          color: Color.BgPrimary,
        }}>
        {'Số lượng task theo assignee'}
      </TextCM>
      <TableCM tableHeaders={['Assignee', 'Quantity']} tableData={dataTable} />
    </View>
  );
};

export default DashboardAsignee;

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#FFFFFF',
    padding: 10,
  },
  avatarContainer: {
    width: 50,
    height: 50,
    borderRadius: 25,
    backgroundColor: '#E0E0E0',
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 10,
  },
  infoContainer: {
    flexDirection: 'column',
  },
  username: {
    color: '#1E3A8A',
    fontFamily: Font.InterSemiBold600,
    fontSize: 16,
  },
  email: {
    color: '#1E3A8A',
    fontSize: 14,
    marginTop: 2,
  },
});
