import {Icon} from '@ui-kitten/components';
import HeaderCM from '../../components/Header/HeaderCM';
import TextCM from '../../components/Text';
import {Image, Pressable, RefreshControl, ScrollView} from 'react-native';
import {LogoTask} from '../../../assets/images';
import {useState} from 'react';
import {Font} from '../../../constants';
import ListTask from './components/list-task';
import ModalFullScreen from '../../components/ModalFullScreen';
import CreateNewTaskScreen from './components/create-new-task';
import styles from './styles';

const BoardScreen = () => {
  const [refreshing, setRefreshing] = useState(false);
  const [isVisiableCreateTask, setIsVisableCreateTask] = useState(false);

  const onRefresh = () => {
    setRefreshing(true);
  };
  return (
    <>
      <HeaderCM
        renderContentRight={() => (
          <Pressable onPress={() => setIsVisableCreateTask(true)}>
            <Icon fill={'#fff'} width={24} height={24} name="plus-outline" />
          </Pressable>
        )}
        showIconBackLeft={false}
        title=""
        renderContentLeftDynamic={() => (
          <Image resizeMode="contain" source={LogoTask} />
        )}
      />
      <ScrollView
        style={styles.ctnBody}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
        }>
        <TextCM style={styles.txtHeader}>Không gian làm việc</TextCM>

        <ListTask refreshing={refreshing} setRefreshing={setRefreshing} />
      </ScrollView>

      <ModalFullScreen
        isVisible={isVisiableCreateTask}
        children={
          <CreateNewTaskScreen onClose={() => setIsVisableCreateTask(false)} />
        }
      />
    </>
  );
};

export default BoardScreen;
