import {FlatList, Pressable, View} from 'react-native';
import {IAttractment, listUploadData} from './helper';
import {useEffect, useState} from 'react';
import {
  useTaskService,
  useUtilsService,
} from '../../../../../../../hooks/apiHooks/useAPI';
import {Icon} from '@ui-kitten/components';
import TextCM from '../../../../../../components/Text';
import AttractmentItem from './component/item';
import DropdownCM from '../../../../../../components/DropDown';
import {
  ChoosePhoto,
  TakePhoto,
} from '../../../../../../components/ImageCropPicker';
import Toast from 'react-native-toast-message';
import {CommonUtils} from '../../../../../../../utils';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import AddUrl from './component/add-url';

type Props = {
  taskId: string;
};

const Attractments = ({taskId}: Props) => {
  const [listAttractment, setListAttractment] = useState<IAttractment[]>([]);
  const [showAddUrl, setShowAddUrl] = useState(false);
  const TaskService = useTaskService();
  const UltisService = useUtilsService();

  useEffect(() => {
    getListAttractment();
  }, []);
  const getListAttractment = async () => {
    const dataResp = await TaskService.getAttractmentById(taskId);
    if (dataResp) {
      setListAttractment(dataResp);
    }
  };

  const handleSelect = (value: string) => {
    switch (value) {
      case 'image':
        handleSelectImage();
        break;
      case 'takePhoto':
        handleTakePhoto();
        break;
      case 'file':
        handleGetFormFile();
        break;
      case 'link':
        setShowAddUrl(true);
        break;
      default:
        break;
    }
  };

  const handleSelectImage = async () => {
    try {
      const dataSelect = (await ChoosePhoto({
        cropping: true,
      })) as any;
      const formData = new FormData();
      formData.append('file', {
        uri: dataSelect?.sourceURL,
        name: dataSelect?.filename,
        type: dataSelect?.mime,
      });
      formData.append(
        'dto',
        JSON.stringify({
          taskId: taskId,
          attr: JSON.stringify({
            name: dataSelect?.filename,
            type: dataSelect?.filename?.split('.')?.slice(-1)?.[0],
          }),
        }),
      );
      const dataResp = await UltisService.updateFile(formData);
      if (dataResp) {
        setListAttractment([...listAttractment, dataResp]);
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {
      console.log(error);
    }
  };

  const handleTakePhoto = async () => {
    try {
      const dataSelect = (await TakePhoto()) as any;
      console.log(dataSelect);
      // const formData = new FormData();
      // formData.append('file', {
      //   uri: dataSelect?.sourceURL,
      //   name: dataSelect?.filename,
      //   type: dataSelect?.mime,
      // });
      // formData.append(
      //   'dto',
      //   JSON.stringify({
      //     taskId: taskId,
      //     attr: JSON.stringify({
      //       name: dataSelect?.filename,
      //       type: dataSelect?.filename?.split('.')?.slice(-1)?.[0],
      //     }),
      //   }),
      // );
      // const dataResp = await UltisService.updateFile(formData);
      // if (dataResp) {
      //   setListAttractment([...listAttractment, dataResp]);
      // } else {
      //   Toast.show({
      //     type: 'error',
      //     text1: 'Thông báo',
      //     text2: 'Có lỗi xảy ra',
      //   });
      // }
    } catch (error) {
      console.log(error);
    }
  };

  const handleGetFormFile = async () => {
    try {
      const dataSelect = await CommonUtils.handleGetFile();
      const formData = new FormData();
      formData.append('file', dataSelect);
      formData.append(
        'dto',
        JSON.stringify({
          taskId: taskId,
          attr: JSON.stringify({
            name: dataSelect?.name,
            type: dataSelect?.name?.split('.')?.slice(-1)?.[0],
          }),
        }),
      );
      const dataResp = await UltisService.updateFile(formData);
      if (dataResp) {
        setListAttractment([dataResp, ...listAttractment]);
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {}
  };

  const handleAddUrl = async (listUrl: string[]) => {
    try {
      const listApi = listUrl.map(data => {
        const formData = new FormData();
        formData.append('file', null);
        formData.append(
          'dto',
          JSON.stringify({
            taskId: taskId,
            attr: JSON.stringify({
              name: data,
              type: 'url',
            }),
            url: data,
          }),
        );
        return UltisService.updateFile(formData);
      });
      const dataResp = await Promise.all(listApi);
      if (dataResp) {
        setListAttractment([...dataResp, ...listAttractment]);
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {
    } finally {
      setShowAddUrl(false);
    }
  };

  return (
    <View style={{paddingVertical: 10, rowGap: 6, flex: 1}}>
      <View
        style={{
          flexDirection: 'row',
          columnGap: 8,
          alignItems: 'center',
          paddingHorizontal: 16,
          flex: 1,
          justifyContent: 'space-between',
        }}>
        <View
          style={{
            flexDirection: 'row',
            columnGap: 8,
            alignItems: 'center',
          }}>
          <Icon name="cloud-upload-outline" width={24} height={24} />
          <TextCM>Attractments</TextCM>
        </View>
        <DropdownCM
          listDropdown={listUploadData}
          renderShowData={
            <View>
              <Icon name="plus-outline" width={24} height={24} />
            </View>
          }
          onChangeItem={item => handleSelect(item.value)}
        />
      </View>

      <FlatList
        contentContainerStyle={{
          paddingHorizontal: 10,
          gap: 10,
        }}
        columnWrapperStyle={{
          gap: 10,
        }}
        numColumns={2}
        data={listAttractment}
        scrollEnabled={false}
        renderItem={({item}) => (
          <AttractmentItem
            setListAttractment={setListAttractment}
            valueItem={item}
          />
        )}
      />

      <ModalFullScreen
        isVisible={showAddUrl}
        children={
          <AddUrl onSave={handleAddUrl} onClose={() => setShowAddUrl(false)} />
        }
      />
    </View>
  );
};

export default Attractments;
